CREATE DATABASE IF NOT EXISTS tienda CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE tienda;
CREATE TABLE IF NOT EXISTS usuarios (id INT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(100) NOT NULL, email VARCHAR(100) NOT NULL UNIQUE, contrasena VARCHAR(255) NOT NULL, rol ENUM('user','admin') NOT NULL DEFAULT 'user', creado DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS productos (id INT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(100) NOT NULL, descripcion TEXT NOT NULL, precio DECIMAL(10,2) NOT NULL, imagen VARCHAR(255) NULL, creado TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS carrito (id_carrito INT AUTO_INCREMENT PRIMARY KEY, id_usuario INT NOT NULL, estado ENUM('abierto','cerrado') NOT NULL DEFAULT 'abierto', FOREIGN KEY (id_usuario) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS detalles_carrito (id_detalle_carrito INT AUTO_INCREMENT PRIMARY KEY, id_carrito INT NOT NULL, id_producto INT NOT NULL, cantidad INT NOT NULL DEFAULT 1, precio_unitario DECIMAL(10,2) NOT NULL, UNIQUE KEY carrito_producto (id_carrito,id_producto), FOREIGN KEY (id_carrito) REFERENCES carrito(id_carrito) ON DELETE CASCADE, FOREIGN KEY (id_producto) REFERENCES productos(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS compras (id_compra INT AUTO_INCREMENT PRIMARY KEY, id_usuario INT NOT NULL, total DECIMAL(10,2) NOT NULL, fecha TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (id_usuario) REFERENCES usuarios(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS detalles_compra (id_detalle INT AUTO_INCREMENT PRIMARY KEY, id_compra INT NOT NULL, id_producto INT NOT NULL, cantidad INT NOT NULL, precio_unitario DECIMAL(10,2) NOT NULL, subtotal DECIMAL(10,2) NOT NULL, FOREIGN KEY (id_compra) REFERENCES compras(id_compra) ON DELETE CASCADE, FOREIGN KEY (id_producto) REFERENCES productos(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS favoritos (id INT AUTO_INCREMENT PRIMARY KEY, id_usuario INT NOT NULL, id_producto INT NOT NULL, UNIQUE KEY usuario_producto (id_usuario,id_producto), FOREIGN KEY (id_usuario) REFERENCES usuarios(id) ON DELETE CASCADE, FOREIGN KEY (id_producto) REFERENCES productos(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tickets (id_ticket INT AUTO_INCREMENT PRIMARY KEY, numero_ticket VARCHAR(20) NOT NULL UNIQUE, id_compra INT NOT NULL, pdf_path VARCHAR(255) NULL, fecha TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (id_compra) REFERENCES compras(id_compra) ON DELETE CASCADE);
INSERT INTO productos (nombre, descripcion, precio, imagen) SELECT 'The Wanderer','Transmisión clásica recuperada del yermo.',120.00,NULL WHERE NOT EXISTS (SELECT 1 FROM productos);
INSERT INTO productos (nombre, descripcion, precio, imagen) SELECT 'Maybe','Señal de jazz para explorar.',150.00,NULL WHERE NOT EXISTS (SELECT 1 FROM productos WHERE nombre='Maybe');
INSERT INTO productos (nombre, descripcion, precio, imagen) SELECT 'Wanderer Protocol','Instrumental exclusivo Vault-Tec.',200.00,NULL WHERE NOT EXISTS (SELECT 1 FROM productos WHERE nombre='Wanderer Protocol');
